ALTER TABLE selected_products MODIFY integration_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, MODIFY dropi_id BIGINT NULL, ADD COLUMN source VARCHAR(8) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'dropi', ADD CONSTRAINT selected_products_source_ck CHECK ((source='dropi' AND integration_id IS NOT NULL AND dropi_id IS NOT NULL) OR (source='own' AND integration_id IS NULL AND dropi_id IS NULL))